"""
Binary classes to allow storage and arithmetic result.
"""

from enum import IntEnum
from dataclasses import dataclass
from typing import Final

class Bit(IntEnum):
    """Primitive bit representation: strictly 1 or 0, ON or OFF, TRUE or FALSE."""
    FALSE = 0
    TRUE = 1

class Radix(IntEnum):
    """Common radix types supported by our conversion pipelines."""
    BIN = 2
    OCT = 8
    DEC = 10
    HEX = 16

@dataclass(frozen=True, slots=True, kw_only=True)
class ALUFlags:
    """Status flags generated by the Arithmetic Logic Unit (ALU)."""
    negative: bool # Negative (Sign) Flag: set if the resultant MSB is 1
    zero: bool     # Zero Flag: set if the resultant bit pattern is all zeros
    carry: bool    # Carry Flag: set if an unsigned carry occurred out of the MSB
    overflow: bool # Overflow Flag: set if a signed Two's Complement overflow occurred

    def __str__(self) -> str:
        """Return a four-character string summarizing all of the status flags."""
        return (('N' if self.negative else '-')
            + ('Z' if self.zero else '-')
            + ('C' if self.carry else '-')
            + ('V' if self.overflow else '-'))

class BitVector:
    """Fixed-width bit vector representing a sequence of N bits from LSB (index 0) to MSB (index N-1)."""
    MAX_BITS: Final = 64

    @property
    def width(self):
        return len(self.data)

    def __init__(self, value, width: int = 0) -> None:
        """Allow creation from any of string (of 1s and 0s), integer (plus bit-width) or array of Bit."""
        self.data = None
        if type(value) == type([]):
            width = len(value)
            self.data = value
        elif type(value) == type(''):
            width = len(value)
            value = int('0b' + value, 2)
        elif type(value) != type(0):
            raise ValueError('BitVector.value must be an int, str or array of Bit')
        if width < 1 or width > self.MAX_BITS:
            raise ValueError(f'BitVector.width must be between 1 and {self.MAX_BITS} (have {width})')
        if self.data == None:
            self.data = [Bit.TRUE if value & (1 << (width - bit - 1)) != 0 else Bit.FALSE
                        for bit in range(width)]

    def __getitem__(self, index: int) -> Bit:
        """Retrieves the bit at position index, where index 0 is the LSB and (width - 1) is the MSB."""
        if (index < 0 or index >= self.width):
            raise IndexError(f'Bit index out of range (have {index}, maximum {self.width - 1})')
        return self.data[self.width - index - 1]
    
    def __repr__(self) -> str:
        return f"BitVector(0b{self.__str__()},{self.width})"
    
    def __str__(self) -> str:
        result = ''
        for index in range(self.width):
            result += '1' if self.data[index] == Bit.TRUE else '0'
        return result
    
    def asUnsignedInteger(self) -> int:
        result = 0
        for index in range(self.width):
            result += 1 << (self.width - index - 1) if self.data[index] == Bit.TRUE else 0
        return result
    
    def asSignedInteger(self) -> int:
        result = -(1 << (self.width - 1)) if self.data[0] == Bit.TRUE else 0 # MSB is sign bit
        result += BitVector(self.data[1:]).asUnsignedInteger() # All other bits treated as unsigned integer
        return result

@dataclass(frozen=True, slots=True, kw_only=True)
class ArithmeticResult:
    """Result of an arithmetic operation containing the output bits and ALU flags."""
    bits: BitVector
    flags: ALUFlags